..@import "tailwindcss";

:root {
    --background: #ffffff;
    --foreground: #171717;
}

@theme inline {
    --color-background: var(--background);
    --color-foreground: var(--foreground);
    --font-sans: var(--font-geist-sans);
    --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
    :root {
        --background: #fff8f0;
        /* --foreground: #ededed; */
    }
}

body {
    background: var(--background);
    /* color: var(--foreground); */
    font-family: Arial, Helvetica, sans-serif;
    margin: 0;
}

html,
body {
    height: 100%;
}

body {
    min-height: 100dvh;
    overflow: hidden;
}

/*
  Added from globals-patch.css.
  Both GameSetup and GameBoard inherit this background.
*/
body {
    background-color: #fff8f0;
    margin: 0;
}

/* UNO toast theme for Sonner */
.uno-toast {
    background: var(--ui-surface, #fff8f0) !important;
    color: var(--ui-text, #1a0f00) !important;
    border: 1px solid var(--ui-line, rgba(26, 15, 0, 0.2)) !important;
    border-left: 4px solid var(--ui-line, rgba(26, 15, 0, 0.2)) !important;
    border-radius: 0 !important;
    box-shadow: 0 10px 24px
        color-mix(in srgb, var(--ui-bg, #fff8f0) 40%, #000 60%) !important;
    font-family: "Courier Prime", monospace !important;
    padding: 10px 12px !important;
    gap: 6px !important;
    min-height: 0 !important;
    width: min(320px, calc(100vw - 24px)) !important;
}

.uno-toast-title {
    font-family: "Bebas Neue", cursive !important;
    font-size: 17px !important;
    letter-spacing: 0.05em !important;
    line-height: 1 !important;
    color: var(--ui-text, #1a0f00) !important;
    margin-bottom: 1px !important;
}

.uno-toast-description {
    font-family: "Courier Prime", monospace !important;
    font-size: 10px !important;
    letter-spacing: 0.05em !important;
    text-transform: uppercase !important;
    color: var(--ui-muted, rgba(26, 15, 0, 0.65)) !important;
    line-height: 1.35 !important;
}

.uno-toast-action,
.uno-toast-cancel,
.uno-toast-close {
    font-family: "Courier Prime", monospace !important;
    font-size: 9px !important;
    font-weight: 700 !important;
    letter-spacing: 0.1em !important;
    text-transform: uppercase !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

.uno-toast-action {
    background: var(--ui-text, #1a0f00) !important;
    color: var(--ui-bg, #fff8f0) !important;
    border: none !important;
}

.uno-toast-cancel,
.uno-toast-close {
    background: transparent !important;
    color: var(--ui-muted, rgba(26, 15, 0, 0.65)) !important;
    border: 1px solid var(--ui-line, rgba(26, 15, 0, 0.2)) !important;
}

[data-sonner-toaster] {
    --normal-bg: var(--ui-surface, #fff8f0) !important;
    --normal-text: var(--ui-text, #1a0f00) !important;
    --normal-border: var(--ui-line, rgba(26, 15, 0, 0.2)) !important;
}

.uno-toast-success {
    border-left-color: var(--ui-accent-green, #1e6b3a) !important;
}

.uno-toast-error {
    border-left-color: var(--ui-accent-red, #c0392b) !important;
}

.uno-toast-warning {
    border-left-color: var(--ui-accent-yellow, #d4a017) !important;
}

.uno-toast-info {
    border-left-color: var(--ui-accent-blue, #1a4f8a) !important;
}

