heimport type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import { Toaster } from "sonner";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "UNO — Card Game",
  description: "A customisable UNO-style card game with bot support and house rules.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body
        className={`${geistSans.variable} ${geistMono.variable} antialiased`}
      >
        {children}
        <Toaster
          position="bottom-right"
          richColors={false}
          closeButton
          expand={false}
          visibleToasts={3}
          offset={12}
          toastOptions={{
            duration: 2800,
            classNames: {
              toast: "uno-toast",
              title: "uno-toast-title",
              description: "uno-toast-description",
              actionButton: "uno-toast-action",
              cancelButton: "uno-toast-cancel",
              closeButton: "uno-toast-close",
              success: "uno-toast-success",
              error: "uno-toast-error",
              warning: "uno-toast-warning",
              info: "uno-toast-info",
            },
          }}
        />
      </body>
    </html>
  );
}

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import { Toaster } from "sonner";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "UNO — Card Game",
  description: "A customisable UNO-style card game with bot support and house rules.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <head>
        <script
          dangerouslySetInnerHTML={{
            __html: `
              (function() {
                const PREFERRED_THEME_KEY = 'uno.preferred.theme';
                const themeVars = {
                  paper: {
                    '--ui-bg': '#fafafa',
                    '--ui-surface': '#ffffff',
                    '--ui-text': '#212121',
                    '--ui-muted': 'rgba(33,33,33,0.54)',
                    '--ui-line': 'rgba(0,0,0,0.12)',
                    '--ui-accent-red': '#e53935',
                    '--ui-accent-yellow': '#f9a825',
                    '--ui-accent-green': '#43a047',
                    '--ui-accent-blue': '#1e88e5',
                  },
                  midnight: {
                    '--ui-bg': '#121212',
                    '--ui-surface': '#1e1e1e',
                    '--ui-text': '#e0e0e0',
                    '--ui-muted': 'rgba(224,224,224,0.6)',
                    '--ui-line': 'rgba(255,255,255,0.12)',
                    '--ui-accent-red': '#ef5350',
                    '--ui-accent-yellow': '#fdd835',
                    '--ui-accent-green': '#66bb6a',
                    '--ui-accent-blue': '#42a5f5',
                  },
                  forest: {
                    '--ui-bg': '#e0f2f1',
                    '--ui-surface': '#ffffff',
                    '--ui-text': '#004d40',
                    '--ui-muted': 'rgba(0,77,64,0.6)',
                    '--ui-line': 'rgba(0,77,64,0.15)',
                    '--ui-accent-red': '#e53935',
                    '--ui-accent-yellow': '#f9a825',
                    '--ui-accent-green': '#00897b',
                    '--ui-accent-blue': '#1e88e5',
                  },
                  sunset: {
                    '--ui-bg': '#1a0033',
                    '--ui-surface': '#2d0057',
                    '--ui-text': '#ede7f6',
                    '--ui-muted': 'rgba(237,231,246,0.65)',
                    '--ui-line': 'rgba(237,231,246,0.18)',
                    '--ui-accent-red': '#ef9a9a',
                    '--ui-accent-yellow': '#fff59d',
                    '--ui-accent-green': '#a5d6a7',
                    '--ui-accent-blue': '#ce93d8',
                  },
                };

                let theme = 'midnight';
                try {
                  const stored = localStorage.getItem(PREFERRED_THEME_KEY);
                  if (stored && (stored === 'paper' || stored === 'forest' || stored === 'sunset')) {
                    theme = stored;
                  }
                } catch {}

                const vars = themeVars[theme] || themeVars.midnight;
                Object.entries(vars).forEach(([key, value]) => {
                  document.documentElement.style.setProperty(key, value);
                });
                document.documentElement.style.backgroundColor = vars['--ui-bg'];
              })();
            `,
          }}
        />
      </head>
      <body
        className={`${geistSans.variable} ${geistMono.variable} antialiased`}
      >
        {children}
        <Toaster
          position="bottom-right"
          richColors={false}
          closeButton
          expand={false}
          visibleToasts={3}
          offset={12}
          toastOptions={{
            duration: 2800,
            classNames: {
              toast: "uno-toast",
              title: "uno-toast-title",
              description: "uno-toast-description",
              actionButton: "uno-toast-action",
              cancelButton: "uno-toast-cancel",
              closeButton: "uno-toast-close",
              success: "uno-toast-success",
              error: "uno-toast-error",
              warning: "uno-toast-warning",
              info: "uno-toast-info",
            },
          }}
        />
      </body>
    </html>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { GameRules } from "../types/rules";
import { useUnoGame } from "../hooks/useUnoGame";
import { useUnoOnlineGame } from "../hooks/useUnoOnlineGame";
import GameBoard from "../components/GameBoard";
import GameSetup from "../components/GameSetup";
import HomeScreen from "../components/home/HomeScreen";
import OnlineLobby from "../components/OnlineLobby";
import SettingsModal from "../components/SettingsModal";
import { SetupUtilityBar } from "../components/ui/PageChrome";
import { toast } from "sonner";

const SHARED_RULES_KEY = "uno.shared.rules";
const PREFERRED_THEME_KEY = "uno.preferred.theme";
const ONLINE_PREFILL_FRIEND_CODE_KEY = "uno.online.prefill.friendCode";
const ONLINE_PLAYER_NAME_KEY = "uno.online.playerName";

type ThemeName = "paper" | "midnight" | "forest" | "sunset";

const THEMES: Record<
  ThemeName,
  { label: string; vars: Record<string, string> }
> = {
  paper: {
    label: "Light",
    vars: {
      "--ui-bg": "#fafafa",
      "--ui-surface": "#ffffff",
      "--ui-text": "#212121",
      "--ui-muted": "rgba(33,33,33,0.54)",
      "--ui-line": "rgba(0,0,0,0.12)",
      "--ui-accent-red": "#e53935",
      "--ui-accent-yellow": "#f9a825",
      "--ui-accent-green": "#43a047",
      "--ui-accent-blue": "#1e88e5",
    },
  },
  midnight: {
    label: "Dark",
    vars: {
      "--ui-bg": "#121212",
      "--ui-surface": "#1e1e1e",
      "--ui-text": "#e0e0e0",
      "--ui-muted": "rgba(224,224,224,0.6)",
      "--ui-line": "rgba(255,255,255,0.12)",
      "--ui-accent-red": "#ef5350",
      "--ui-accent-yellow": "#fdd835",
      "--ui-accent-green": "#66bb6a",
      "--ui-accent-blue": "#42a5f5",
    },
  },
  forest: {
    label: "Teal",
    vars: {
      "--ui-bg": "#e0f2f1",
      "--ui-surface": "#ffffff",
      "--ui-text": "#004d40",
      "--ui-muted": "rgba(0,77,64,0.6)",
      "--ui-line": "rgba(0,77,64,0.15)",
      "--ui-accent-red": "#e53935",
      "--ui-accent-yellow": "#f9a825",
      "--ui-accent-green": "#00897b",
      "--ui-accent-blue": "#1e88e5",
    },
  },
  sunset: {
    label: "Purple",
    vars: {
      "--ui-bg": "#1a0033",
      "--ui-surface": "#2d0057",
      "--ui-text": "#ede7f6",
      "--ui-muted": "rgba(237,231,246,0.65)",
      "--ui-line": "rgba(237,231,246,0.18)",
      "--ui-accent-red": "#ef9a9a",
      "--ui-accent-yellow": "#fff59d",
      "--ui-accent-green": "#a5d6a7",
      "--ui-accent-blue": "#ce93d8",
    },
  },
};

const DEFAULT_RULES: Partial<GameRules> = {
  stackDraw2: false,
  stackWild4: false,
  allowWild4OnDraw2: false,
  drawUntilPlayable: false,
  reverseActsAsSkipInTwoPlayer: true,
  mustDeclareUno: true,
  allowStartingActionCard: true,
  allowDiscardAll: false,
  allowShuffleCard: false,
  allowDoublePlaySameNumber: false,
  maxPlayers: 4,
};

function getInitialRules(): Partial<GameRules> {
  if (typeof window === "undefined") return DEFAULT_RULES;
  try {
    const raw = window.localStorage.getItem(SHARED_RULES_KEY);
    if (!raw) return DEFAULT_RULES;
    const parsed = JSON.parse(raw) as Partial<GameRules> & {
      shuffleHandsOnZero?: boolean;
    };
    return {
      ...DEFAULT_RULES,
      ...parsed,
      allowShuffleCard:
        parsed.allowShuffleCard ??
        parsed.shuffleHandsOnZero ??
        DEFAULT_RULES.allowShuffleCard,
    };
  } catch {
    return DEFAULT_RULES;
  }
}

function getInitialTheme(): ThemeName {
  if (typeof window === "undefined") return "paper";
  try {
    const raw = window.localStorage.getItem(PREFERRED_THEME_KEY);
    return raw === "midnight" || raw === "forest" || raw === "sunset"
      ? raw
      : "paper";
  } catch {
    return "paper";
  }
}

// ── Root ───────────────────────────────────────────────────────────────────────
export default function Home() {
  const [mode, setMode] = useState<"online" | "computer">("computer");
  const [view, setView] = useState<"home" | "computer" | "friends">("home");
  const [panel, setPanel] = useState<"create" | "join">("create");
  const [theme, setTheme] = useState<ThemeName>("paper");
  const [showS, setShowS] = useState(false);
  const [rules, setRules] = useState<Partial<GameRules>>(DEFAULT_RULES);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setTheme(getInitialTheme());
      setRules(getInitialRules());
      setMounted(true);
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const local = useUnoGame();
  const online = useUnoOnlineGame();
  const api = mode === "computer" ? local : online;

  useEffect(() => {
    if (mounted) {
      try {
        window.localStorage.setItem(SHARED_RULES_KEY, JSON.stringify(rules));
      } catch {}
    }
  }, [rules, mounted]);

  useEffect(() => {
    if (mounted) {
      try {
        window.localStorage.setItem(PREFERRED_THEME_KEY, theme);
      } catch {}
    }
    const root = document.documentElement;
    for (const [k, v] of Object.entries(THEMES[theme].vars))
      root.style.setProperty(k, v);
  }, [theme, mounted]);

  const cycleTheme = () => {
    const order: ThemeName[] = ["paper", "midnight", "forest", "sunset"];
    setTheme((p) => order[(order.indexOf(p) + 1) % order.length]);
  };

  const copyCode = async () => {
    if (!online.friendCode) return;
    try {
      await navigator.clipboard.writeText(online.friendCode);
      toast.success("Friend code copied.");
    } catch {
      toast.error("Could not copy friend code.");
    }
  };

  const label = THEMES[theme].label;

  const settingsModal = (
    <SettingsModal
      open={showS}
      rules={rules}
      friendCode={online.friendCode}
      onCopyFriendCode={() => {
        void copyCode();
      }}
      onChange={setRules}
      onClose={() => setShowS(false)}
    />
  );

  const topBar = (
    <SetupUtilityBar
      themeLabel={label}
      onTheme={cycleTheme}
      onSettings={() => setShowS(true)}
    />
  );

  // Active game
  if (api.game) {
    const currentGame = api.game;
    return (
      <>
        <GameBoard
          gameApi={api as ReturnType<typeof useUnoGame>}
          onReset={() => {
            api.resetGame();
            setMode("computer");
            setView("home");
          }}
          onDealAgain={() => {
            if (mode === "computer") {
              local.startGame(
                currentGame.players.map((player) => player.name),
                currentGame.rules,
                currentGame.players.map((player) => player.isBot),
              );
              return;
            }
            void online.startOnlineGame(currentGame.rules);
          }}
          onOpenSettings={() => setShowS(true)}
          onCycleTheme={cycleTheme}
          currentThemeLabel={label}
        />
        {settingsModal}
      </>
    );
  }

  if (view === "home") {
    return (
      <>
        <HomeScreen
          themeLabel={label}
          onTheme={cycleTheme}
          onSettings={() => setShowS(true)}
          onComputer={() => {
            setMode("computer");
            setView("computer");
          }}
          onFriends={() => {
            setMode("online");
            setPanel("create");
            setView("friends");
          }}
          onCheckFriendOnline={online.checkFriendOnline}
          onFriendQuickInvite={async (friendCode) => {
            let playerName = "Player 1";
            try {
              const stored = window.localStorage.getItem(
                ONLINE_PLAYER_NAME_KEY,
              );
              if (stored && stored.trim())
                playerName = stored.trim().slice(0, 18);
              window.localStorage.setItem(
                ONLINE_PREFILL_FRIEND_CODE_KEY,
                friendCode,
              );
            } catch {
              // Ignore storage issues and still continue.
            }

            const invited = await online.sendFriendInvite(
              friendCode,
              playerName,
            );
            if (!invited) {
              toast.error(online.error ?? "Could not send invite.");
              return false;
            }

            setMode("online");
            setPanel("create");
            setView("friends");
            return true;
          }}
        />
        {settingsModal}
      </>
    );
  }

  if (view === "computer") {
    return (
      <>
        <GameSetup
          controls={topBar}
          onBack={() => setView("home")}
          onStart={(names, botFlags) => {
            setMode("computer");
            local.startGame(names, rules, botFlags);
          }}
        />
        {settingsModal}
      </>
    );
  }

  return (
    <>
      <OnlineLobby
        controls={topBar}
        onBack={() => setView("home")}
        initialPanel={panel}
        connected={online.connected}
        room={online.room}
        playerId={online.playerId}
        friendCode={online.friendCode}
        incomingInvites={online.incomingInvites}
        outgoingInvites={online.outgoingInvites}
        error={online.error}
        onSyncPresence={online.syncPresence}
        onCreateRoom={online.createRoom}
        onJoinRoom={online.joinRoom}
        onSendFriendInvite={online.sendFriendInvite}
        onAcceptFriendInvite={online.acceptFriendInvite}
        onDeclineFriendInvite={online.declineFriendInvite}
        onLeaveRoom={online.leaveRoom}
        onStartGame={() => {
          setMode("online");
          return online.startOnlineGame(rules);
        }}
        onAddBotSeat={online.addBotToRoom}
        onKickPlayer={online.kickPlayer}
        onCheckFriendOnline={online.checkFriendOnline}
      />
      {settingsModal}
    </>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { GameRules } from "../types/rules";
import { useUnoGame } from "../hooks/useUnoGame";
import { useUnoOnlineGame } from "../hooks/useUnoOnlineGame";
import GameBoard from "../components/GameBoard";
import GameSetup from "../components/GameSetup";
import HomeScreen from "../components/home/HomeScreen";
import OnlineLobby from "../components/OnlineLobby";
import SettingsModal from "../components/SettingsModal";
import { SetupUtilityBar } from "../components/ui/PageChrome";
import { toast } from "sonner";

const SHARED_RULES_KEY = "uno.shared.rules";
const PREFERRED_THEME_KEY = "uno.preferred.theme";
const ONLINE_PREFILL_FRIEND_CODE_KEY = "uno.online.prefill.friendCode";
const ONLINE_PLAYER_NAME_KEY = "uno.online.playerName";

type ThemeName = "paper" | "midnight" | "forest" | "sunset";

const THEMES: Record<
  ThemeName,
  { label: string; vars: Record<string, string> }
> = {
  paper: {
    label: "Light",
    vars: {
      "--ui-bg": "#fafafa",
      "--ui-surface": "#ffffff",
      "--ui-text": "#212121",
      "--ui-muted": "rgba(33,33,33,0.54)",
      "--ui-line": "rgba(0,0,0,0.12)",
      "--ui-accent-red": "#e53935",
      "--ui-accent-yellow": "#f9a825",
      "--ui-accent-green": "#43a047",
      "--ui-accent-blue": "#1e88e5",
    },
  },
  midnight: {
    label: "Dark",
    vars: {
      "--ui-bg": "#121212",
      "--ui-surface": "#1e1e1e",
      "--ui-text": "#e0e0e0",
      "--ui-muted": "rgba(224,224,224,0.6)",
      "--ui-line": "rgba(255,255,255,0.12)",
      "--ui-accent-red": "#ef5350",
      "--ui-accent-yellow": "#fdd835",
      "--ui-accent-green": "#66bb6a",
      "--ui-accent-blue": "#42a5f5",
    },
  },
  forest: {
    label: "Teal",
    vars: {
      "--ui-bg": "#e0f2f1",
      "--ui-surface": "#ffffff",
      "--ui-text": "#004d40",
      "--ui-muted": "rgba(0,77,64,0.6)",
      "--ui-line": "rgba(0,77,64,0.15)",
      "--ui-accent-red": "#e53935",
      "--ui-accent-yellow": "#f9a825",
      "--ui-accent-green": "#00897b",
      "--ui-accent-blue": "#1e88e5",
    },
  },
  sunset: {
    label: "Purple",
    vars: {
      "--ui-bg": "#1a0033",
      "--ui-surface": "#2d0057",
      "--ui-text": "#ede7f6",
      "--ui-muted": "rgba(237,231,246,0.65)",
      "--ui-line": "rgba(237,231,246,0.18)",
      "--ui-accent-red": "#ef9a9a",
      "--ui-accent-yellow": "#fff59d",
      "--ui-accent-green": "#a5d6a7",
      "--ui-accent-blue": "#ce93d8",
    },
  },
};

const DEFAULT_RULES: Partial<GameRules> = {
  stackDraw2: false,
  stackWild4: false,
  allowWild4OnDraw2: false,
  drawUntilPlayable: false,
  reverseActsAsSkipInTwoPlayer: true,
  mustDeclareUno: true,
  allowStartingActionCard: true,
  allowDiscardAll: false,
  allowShuffleCard: false,
  allowDoublePlaySameNumber: false,
  maxPlayers: 4,
};

function getInitialRules(): Partial<GameRules> {
  if (typeof window === "undefined") return DEFAULT_RULES;
  try {
    const raw = window.localStorage.getItem(SHARED_RULES_KEY);
    if (!raw) return DEFAULT_RULES;
    const parsed = JSON.parse(raw) as Partial<GameRules> & {
      shuffleHandsOnZero?: boolean;
    };
    return {
      ...DEFAULT_RULES,
      ...parsed,
      allowShuffleCard:
        parsed.allowShuffleCard ??
        parsed.shuffleHandsOnZero ??
        DEFAULT_RULES.allowShuffleCard,
    };
  } catch {
    return DEFAULT_RULES;
  }
}

function getInitialTheme(): ThemeName {
  if (typeof window === "undefined") return "midnight";
  try {
    const raw = window.localStorage.getItem(PREFERRED_THEME_KEY);
    return raw === "paper" || raw === "forest" || raw === "sunset"
      ? raw
      : "midnight";
  } catch {
    return "midnight";
  }
}

// ── Root ───────────────────────────────────────────────────────────────────────
export default function Home() {
  const [mode, setMode] = useState<"online" | "computer">("computer");
  const [view, setView] = useState<"home" | "computer" | "friends">("home");
  const [panel, setPanel] = useState<"create" | "join">("create");
  const [theme, setTheme] = useState<ThemeName>("midnight");
  const [showS, setShowS] = useState(false);
  const [rules, setRules] = useState<Partial<GameRules>>(DEFAULT_RULES);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setTheme(getInitialTheme());
      setRules(getInitialRules());
      setMounted(true);
    }, 0);
    return () => clearTimeout(timer);
  }, []);

  const local = useUnoGame();
  const online = useUnoOnlineGame();
  const api = mode === "computer" ? local : online;

  useEffect(() => {
    if (mounted) {
      try {
        window.localStorage.setItem(SHARED_RULES_KEY, JSON.stringify(rules));
      } catch {}
    }
  }, [rules, mounted]);

  useEffect(() => {
    if (mounted) {
      try {
        window.localStorage.setItem(PREFERRED_THEME_KEY, theme);
      } catch {}
    }
    const root = document.documentElement;
    for (const [k, v] of Object.entries(THEMES[theme].vars))
      root.style.setProperty(k, v);
  }, [theme, mounted]);

  const cycleTheme = () => {
    const order: ThemeName[] = ["paper", "midnight", "forest", "sunset"];
    setTheme((p) => order[(order.indexOf(p) + 1) % order.length]);
  };

  const copyCode = async () => {
    if (!online.friendCode) return;
    try {
      await navigator.clipboard.writeText(online.friendCode);
      toast.success("Friend code copied.");
    } catch {
      toast.error("Could not copy friend code.");
    }
  };

  const label = THEMES[theme].label;

  const settingsModal = (
    <SettingsModal
      open={showS}
      rules={rules}
      friendCode={online.friendCode}
      onCopyFriendCode={() => {
        void copyCode();
      }}
      onChange={setRules}
      onClose={() => setShowS(false)}
    />
  );

  const topBar = (
    <SetupUtilityBar
      themeLabel={label}
      onTheme={cycleTheme}
      onSettings={() => setShowS(true)}
    />
  );

  // Active game
  if (api.game) {
    const currentGame = api.game;
    return (
      <>
        <GameBoard
          gameApi={api as ReturnType<typeof useUnoGame>}
          onReset={() => {
            api.resetGame();
            setMode("computer");
            setView("home");
          }}
          onDealAgain={() => {
            if (mode === "computer") {
              local.startGame(
                currentGame.players.map((player) => player.name),
                currentGame.rules,
                currentGame.players.map((player) => player.isBot),
              );
              return;
            }
            void online.startOnlineGame(currentGame.rules);
          }}
          onOpenSettings={() => setShowS(true)}
          onCycleTheme={cycleTheme}
          currentThemeLabel={label}
        />
        {settingsModal}
      </>
    );
  }

  if (view === "home") {
    return (
      <>
        <HomeScreen
          themeLabel={label}
          onTheme={cycleTheme}
          onSettings={() => setShowS(true)}
          onComputer={() => {
            setMode("computer");
            setView("computer");
          }}
          onFriends={() => {
            setMode("online");
            setPanel("create");
            setView("friends");
          }}
          onCheckFriendOnline={online.checkFriendOnline}
          onFriendQuickInvite={async (friendCode) => {
            let playerName = "Player 1";
            try {
              const stored = window.localStorage.getItem(
                ONLINE_PLAYER_NAME_KEY,
              );
              if (stored && stored.trim())
                playerName = stored.trim().slice(0, 18);
              window.localStorage.setItem(
                ONLINE_PREFILL_FRIEND_CODE_KEY,
                friendCode,
              );
            } catch {
              // Ignore storage issues and still continue.
            }

            const invited = await online.sendFriendInvite(
              friendCode,
              playerName,
            );
            if (!invited) {
              toast.error(online.error ?? "Could not send invite.");
              return false;
            }

            setMode("online");
            setPanel("create");
            setView("friends");
            return true;
          }}
        />
        {settingsModal}
      </>
    );
  }

  if (view === "computer") {
    return (
      <>
        <GameSetup
          controls={topBar}
          onBack={() => setView("home")}
          onStart={(names, botFlags) => {
            setMode("computer");
            local.startGame(names, rules, botFlags);
          }}
        />
        {settingsModal}
      </>
    );
  }

  return (
    <>
      <OnlineLobby
        controls={topBar}
        onBack={() => setView("home")}
        initialPanel={panel}
        connected={online.connected}
        room={online.room}
        playerId={online.playerId}
        friendCode={online.friendCode}
        incomingInvites={online.incomingInvites}
        outgoingInvites={online.outgoingInvites}
        error={online.error}
        onSyncPresence={online.syncPresence}
        onCreateRoom={online.createRoom}
        onJoinRoom={online.joinRoom}
        onSendFriendInvite={online.sendFriendInvite}
        onAcceptFriendInvite={online.acceptFriendInvite}
        onDeclineFriendInvite={online.declineFriendInvite}
        onLeaveRoom={online.leaveRoom}
        onStartGame={() => {
          setMode("online");
          return online.startOnlineGame(rules);
        }}
        onAddBotSeat={online.addBotToRoom}
        onKickPlayer={online.kickPlayer}
        onCheckFriendOnline={online.checkFriendOnline}
      />
      {settingsModal}
    </>
  );
}

