// Popover component
interface PopoverProps {
  trigger: ReactNode;
  children: ReactNode;
  align?: 'left' | 'right' | 'center';
}

export function Popover({ trigger, children, align = 'right' }: PopoverProps) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        contentRef.current &&
        triggerRef.current &&
        !contentRef.current.contains(event.target as Node) &&
        !triggerRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
      }
    }

    if (open) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [open]);

  return (
    <div style={{ position: 'relative', display: 'inline-block' }}>
      <button
        ref={triggerRef}
        onClick={() => setOpen(!open)}
        style={{
          background: 'var(--ui-surface)',
          border: '1px solid var(--ui-line)',
          color: 'var(--ui-muted)',
          padding: '6px 8px',
          cursor: 'pointer',
          transition: 'color 0.12s, border-color 0.12s',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          width: 32,
          height: 32,
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.color = 'var(--ui-text)';
          e.currentTarget.style.borderColor = 'var(--ui-text)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.color = 'var(--ui-muted)';
          e.currentTarget.style.borderColor = 'var(--ui-line)';
        }}
      >
        {trigger}
      </button>

      {open && (
        <div
          ref={contentRef}
          style={{
            position: 'absolute',
            top: 'calc(100% + 8px)',
            [align === 'left' ? 'left' : align === 'center' ? 'left' : 'right']: 0,
            transform: align === 'center' ? 'translateX(-50%)' : undefined,
            minWidth: 200,
            background: 'var(--ui-surface)',
            border: '1px solid var(--ui-line)',
            boxShadow: '0 10px 32px color-mix(in srgb, var(--ui-bg) 40%, #000 60%)',
            zIndex: 1000,
            display: 'grid',
            gap: 0,
          }}
        >
          {children}
        </div>
      )}
    </div>
  );
}

export function PopoverItem({
  onClick,
  children,
  icon,
  selected,
}: {
  onClick: () => void;
  children: ReactNode;
  icon?: ReactNode;
  selected?: boolean;
}) {
  return (
    <button
      onClick={() => {
        onClick();
      }}
      style={{
        background: selected ? 'var(--ui-text)' : 'transparent',
        color: selected ? 'var(--ui-bg)' : 'var(--ui-text)',
        border: 'none',
        borderBottom: '1px solid var(--ui-line)',
        padding: '12px 16px',
        cursor: 'pointer',
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        fontSize: 13,
        fontFamily: "'Courier Prime', monospace",
        textAlign: 'left',
        transition: 'all 0.12s',
      }}
      onMouseEnter={(e) => {
        if (!selected) {
          e.currentTarget.style.background = 'rgba(255,255,255,0.05)';
        }
      }}
      onMouseLeave={(e) => {
        if (!selected) {
          e.currentTarget.style.background = 'transparent';
        }
      }}
    >
      {icon && (
        <span
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 20,
            height: 20,
            color: 'currentColor',
          }}
        >
          {icon}
        </span>
      )}
      <span>{children}</span>
    </button>
  );
}

'use client';

import { useState, type CSSProperties, type MouseEvent, type ReactNode } from 'react';

const SECONDARY_BUTTON_STYLE: CSSProperties = {
  fontFamily: "'Courier Prime', monospace",
  fontSize: 10,
  fontWeight: 700,
  letterSpacing: '0.14em',
  textTransform: 'uppercase',
  background: 'var(--ui-surface)',
  border: '1px solid var(--ui-line)',
  color: 'var(--ui-muted)',
  padding: '6px 11px',
  cursor: 'pointer',
  transition: 'color 0.12s, border-color 0.12s, opacity 0.12s',
};

const PRIMARY_BUTTON_STYLE: CSSProperties = {
  fontFamily: "'Bebas Neue', cursive",
  fontSize: 22,
  letterSpacing: '0.18em',
  background: 'var(--ui-text)',
  color: 'var(--ui-surface)',
  border: 'none',
  padding: '18px 0',
  cursor: 'pointer',
  width: '100%',
  transition: 'opacity 0.12s',
};

function handleButtonMouseEnter(event: MouseEvent<HTMLButtonElement>) {
  if (event.currentTarget.disabled) return;
  event.currentTarget.style.color = 'var(--ui-text)';
  event.currentTarget.style.borderColor = 'var(--ui-text)';
}

function handleButtonMouseLeave(event: MouseEvent<HTMLButtonElement>) {
  event.currentTarget.style.color = 'var(--ui-muted)';
  event.currentTarget.style.borderColor = 'var(--ui-line)';
}

export function PageShell({ children }: { children: ReactNode }) {
  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Courier+Prime:wght@400;700&display=swap');
        *, *::before, *::after { box-sizing: border-box; }
        body { margin: 0; background: var(--ui-bg); }
        @keyframes fadeUp { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:none} }
        @keyframes rowSlideIn { from{opacity:0;transform:translateY(-6px)} to{opacity:1;transform:translateY(0)} }
        .shell-enter { animation: fadeUp 0.28s ease; }
      `}</style>
      <div
        className="shell-enter"
        style={{
          minHeight: '100vh',
          background: 'var(--ui-bg)',
          color: 'var(--ui-text)',
          fontFamily: "'Courier Prime', monospace",
          padding: 'clamp(40px,5vh,64px) clamp(24px,4vw,48px)',
          display: 'flex',
          justifyContent: 'center',
        }}
      >
        <div style={{ width: 'min(1040px, 100%)', display: 'flex', flexDirection: 'column' }}>
          {children}
        </div>
      </div>
    </>
  );
}

export function UtilityButton({
  children,
  disabled = false,
  onClick,
  style,
  type = 'button',
}: {
  children: ReactNode;
  disabled?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
  type?: 'button' | 'submit' | 'reset';
}) {
  return (
    <button
      type={type}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={handleButtonMouseEnter}
      onMouseLeave={handleButtonMouseLeave}
      style={{
        ...SECONDARY_BUTTON_STYLE,
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? 'default' : SECONDARY_BUTTON_STYLE.cursor,
        ...style,
      }}
    >
      {children}
    </button>
  );
}

export function PrimaryButton({
  children,
  disabled = false,
  onClick,
  style,
}: {
  children: ReactNode;
  disabled?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className="setup-primary-btn"
      style={{
        ...PRIMARY_BUTTON_STYLE,
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? 'default' : PRIMARY_BUTTON_STYLE.cursor,
        ...style,
      }}
    >
      {children}
    </button>
  );
}

