export function SetupIntro({
  eyebrow,
  title,
  description,
  onBack,
  trailing,
}: {
  eyebrow: string;
  title: string;
  description: string;
  onBack?: () => void;
  trailing?: ReactNode;
}) {
  return (
    <div style={{ display: 'grid', gap: 12 }}>
      {onBack ? (
        <div>
          <UtilityButton onClick={onBack}>← Back</UtilityButton>
        </div>
      ) : null}

      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 12 }}>
        <div style={{ display: 'grid', gap: 8 }}>
          <p
            style={{
              margin: 0,
              fontSize: 10,
              letterSpacing: '0.22em',
              textTransform: 'uppercase',
              color: 'var(--ui-muted)',
            }}
          >
            {eyebrow}
          </p>
          <h2
            style={{
              margin: 0,
              fontFamily: "'Bebas Neue', cursive",
              fontSize: 34,
              letterSpacing: '0.04em',
              lineHeight: 1,
            }}
          >
            {title}
          </h2>
        </div>

        {trailing}
      </div>

      <p
        style={{
          margin: 0,
          color: 'var(--ui-muted)',
          fontSize: 11,
          letterSpacing: '0.12em',
          textTransform: 'uppercase',
        }}
      >
        {description}
      </p>
    </div>
  );
}

export function SegmentedToggle<T extends string>({
  value,
  options,
  onChange,
}: {
  value: T;
  options: Array<{ value: T; label: string }>;
  onChange: (value: T) => void;
}) {
  return (
    <div style={{ display: 'grid', gridTemplateColumns: `repeat(${options.length}, 1fr)`, border: '2px solid var(--ui-line)', width: '100%' }}>
      {options.map((option) => {
        const selected = option.value === value;
        return (
          <button
            key={option.value}
            type="button"
            onClick={() => onChange(option.value)}
            style={{
              border: 'none',
              padding: '14px 12px',
              cursor: 'pointer',
              background: selected ? 'var(--ui-text)' : 'transparent',
              color: selected ? 'var(--ui-surface)' : 'var(--ui-text)',
              fontSize: 13,
              fontWeight: 700,
              letterSpacing: '0.12em',
              textTransform: 'uppercase',
              fontFamily: "'Courier Prime', monospace",
            }}
          >
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

export function ModeRow({
  label,
  desc,
  onClick,
  last,
}: {
  label: string;
  desc: string;
  onClick: () => void;
  last?: boolean;
}) {
  const [hovered, setHovered] = useState(false);

  return (
    <button
      type="button"
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 16,
        padding: '20px 22px',
        border: '1px solid var(--ui-line)',
        marginBottom: last ? 0 : 8,
        background: hovered ? 'var(--ui-surface)' : 'transparent',
        cursor: 'pointer',
        textAlign: 'left',
        width: '100%',
        transition: 'background 0.12s, border-color 0.12s',
        borderColor: hovered ? 'var(--ui-text)' : 'var(--ui-line)',
        animation: 'rowSlideIn 0.24s ease',
      }}
    >
      <div>
        <p
          style={{
            margin: 0,
            fontFamily: "'Bebas Neue', cursive",
            fontSize: 26,
            letterSpacing: '0.04em',
            color: 'var(--ui-text)',
            lineHeight: 1,
          }}
        >
          {label}
        </p>
        <p
          style={{
            margin: '8px 0 0',
            fontFamily: "'Courier Prime', monospace",
            fontSize: 11,
            letterSpacing: '0.12em',
            color: 'var(--ui-muted)',
            textTransform: 'uppercase',
          }}
        >
          {desc}
        </p>
      </div>
      <span
        style={{
          fontFamily: "'Courier Prime', monospace",
          fontSize: 16,
          color: 'var(--ui-muted)',
          flexShrink: 0,
          transition: 'transform 0.14s',
          transform: hovered ? 'translateX(3px)' : 'none',
        }}
      >
        →
      </span>
    </button>
  );
}

'use client';

import { useState, useEffect, useRef, type CSSProperties, type MouseEvent, type ReactNode } from 'react';

const SECONDARY_BUTTON_STYLE: CSSProperties = {
  fontFamily: "'Courier Prime', monospace",
  fontSize: 10,
  fontWeight: 700,
  letterSpacing: '0.14em',
  textTransform: 'uppercase',
  background: 'var(--ui-surface)',
  border: '1px solid var(--ui-line)',
  color: 'var(--ui-muted)',
  padding: '6px 11px',
  cursor: 'pointer',
  transition: 'color 0.12s, border-color 0.12s, opacity 0.12s',
};

const PRIMARY_BUTTON_STYLE: CSSProperties = {
  fontFamily: "'Bebas Neue', cursive",
  fontSize: 22,
  letterSpacing: '0.18em',
  background: 'var(--ui-text)',
  color: 'var(--ui-surface)',
  border: 'none',
  padding: '18px 0',
  cursor: 'pointer',
  width: '100%',
  transition: 'opacity 0.12s',
};

function handleButtonMouseEnter(event: MouseEvent<HTMLButtonElement>) {
  if (event.currentTarget.disabled) return;
  event.currentTarget.style.color = 'var(--ui-text)';
  event.currentTarget.style.borderColor = 'var(--ui-text)';
}

function handleButtonMouseLeave(event: MouseEvent<HTMLButtonElement>) {
  event.currentTarget.style.color = 'var(--ui-muted)';
  event.currentTarget.style.borderColor = 'var(--ui-line)';
}

export function PageShell({ children }: { children: ReactNode }) {
  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Courier+Prime:wght@400;700&display=swap');
        *, *::before, *::after { box-sizing: border-box; }
        body { margin: 0; background: var(--ui-bg); }
        @keyframes fadeUp { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:none} }
        @keyframes rowSlideIn { from{opacity:0;transform:translateY(-6px)} to{opacity:1;transform:translateY(0)} }
        .shell-enter { animation: fadeUp 0.28s ease; }
      `}</style>
      <div
        className="shell-enter"
        style={{
          minHeight: '100vh',
          background: 'var(--ui-bg)',
          color: 'var(--ui-text)',
          fontFamily: "'Courier Prime', monospace",
          padding: 'clamp(40px,5vh,64px) clamp(24px,4vw,48px)',
          display: 'flex',
          justifyContent: 'center',
        }}
      >
        <div style={{ width: 'min(1040px, 100%)', display: 'flex', flexDirection: 'column' }}>
          {children}
        </div>
      </div>
    </>
  );
}

export function UtilityButton({
  children,
  disabled = false,
  onClick,
  style,
  type = 'button',
}: {
  children: ReactNode;
  disabled?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
  type?: 'button' | 'submit' | 'reset';
}) {
  return (
    <button
      type={type}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={handleButtonMouseEnter}
      onMouseLeave={handleButtonMouseLeave}
      style={{
        ...SECONDARY_BUTTON_STYLE,
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? 'default' : SECONDARY_BUTTON_STYLE.cursor,
        ...style,
      }}
    >
      {children}
    </button>
  );
}

export function PrimaryButton({
  children,
  disabled = false,
  onClick,
  style,
}: {
  children: ReactNode;
  disabled?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className="setup-primary-btn"
      style={{
        ...PRIMARY_BUTTON_STYLE,
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? 'default' : PRIMARY_BUTTON_STYLE.cursor,
        ...style,
      }}
    >
      {children}
    </button>
  );
}

export function UnoWordmark({ compact = false }: { compact?: boolean }) {
  return (
    <h1
      style={{
        margin: 0,
        fontFamily: "'Bebas Neue', cursive",
        fontSize: compact ? 38 : 'clamp(72px,14vw,120px)',
        letterSpacing: '0.02em',
        lineHeight: 1,
      }}
    >
      <span style={{ color: 'var(--ui-accent-red)' }}>U</span>
      <span style={{ color: 'var(--ui-accent-yellow)' }}>N</span>
      <span style={{ color: 'var(--ui-accent-green)' }}>O</span>
    </h1>
  );
}

export function HomeUtilityBar({
  themeLabel,
  onTheme,
  onSettings,
  onFriends,
}: {
  themeLabel: string;
  onTheme: () => void;
  onSettings: () => void;
  onFriends?: () => void;
}) {
  const [settingsOpen, setSettingsOpen] = useState(false);
  const settingsRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(e: Event) {
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node)) {
        setSettingsOpen(false);
      }
    }
    if (settingsOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [settingsOpen]);

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 6,
        padding: '14px 0',
        borderBottom: '1px solid var(--ui-line)',
        marginBottom: 16,
      }}
    >
      <div style={{ marginLeft: 'auto', display: 'flex', gap: 8 }}>
        {/* Settings Popover */}
        <div ref={settingsRef} style={{ position: 'relative' }}>
          <button
            onClick={() => setSettingsOpen(!settingsOpen)}
            title="Settings"
            style={{
              background: 'var(--ui-surface)',
              border: '1px solid var(--ui-line)',
              color: 'var(--ui-muted)',
              padding: '6px 11px',
              cursor: 'pointer',
              fontFamily: "'Courier Prime', monospace",
              fontSize: 14,
              fontWeight: 700,
              transition: 'all 0.12s',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.color = 'var(--ui-text)';
              e.currentTarget.style.borderColor = 'var(--ui-text)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.color = 'var(--ui-muted)';
              e.currentTarget.style.borderColor = 'var(--ui-line)';
            }}
          >
            ⚙️
          </button>

          {settingsOpen && (
            <div
              style={{
                position: 'absolute',
                top: 'calc(100% + 8px)',
                right: 0,
                background: 'var(--ui-surface)',
                border: '1px solid var(--ui-line)',
                boxShadow: '0 10px 24px rgba(0,0,0,0.3)',
                zIndex: 1000,
                minWidth: 200,
              }}
            >
              {/* Profile */}
              <button
                onClick={() => {
                  onSettings();
                  setSettingsOpen(false);
                }}
                style={{
                  width: '100%',
                  background: 'transparent',
                  border: 'none',
                  borderBottom: '1px solid var(--ui-line)',
                  padding: '10px 14px',
                  textAlign: 'left',
                  cursor: 'pointer',
                  color: 'var(--ui-text)',
                  fontSize: 12,
                  fontFamily: "'Courier Prime', monospace",
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  transition: 'all 0.12s',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = 'var(--ui-text)';
                  e.currentTarget.style.color = 'var(--ui-bg)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = 'transparent';
                  e.currentTarget.style.color = 'var(--ui-text)';
                }}
              >
                <span></span> Profile
              </button>

              {/* Controls */}
              <button
                onClick={() => {
                  onSettings();
                  setSettingsOpen(false);
                }}
                style={{
                  width: '100%',
                  background: 'transparent',
                  border: 'none',
                  borderBottom: '1px solid var(--ui-line)',
                  padding: '10px 14px',
                  textAlign: 'left',
                  cursor: 'pointer',
                  color: 'var(--ui-text)',
                  fontSize: 12,
                  fontFamily: "'Courier Prime', monospace",
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  transition: 'all 0.12s',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = 'var(--ui-text)';
                  e.currentTarget.style.color = 'var(--ui-bg)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = 'transparent';
                  e.currentTarget.style.color = 'var(--ui-text)';
                }}
              >
                <span></span> Controls
              </button>

              {/* Audio */}
              <button
                onClick={() => {
                  onSettings();
                  setSettingsOpen(false);
                }}
                style={{
                  width: '100%',
                  background: 'transparent',
                  border: 'none',
                  borderBottom: '1px solid var(--ui-line)',
                  padding: '10px 14px',
                  textAlign: 'left',
                  cursor: 'pointer',
                  color: 'var(--ui-text)',
                  fontSize: 12,
                  fontFamily: "'Courier Prime', monospace",
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  transition: 'all 0.12s',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = 'var(--ui-text)';
                  e.currentTarget.style.color = 'var(--ui-bg)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = 'transparent';
                  e.currentTarget.style.color = 'var(--ui-text)';
                }}
              >
                <span></span> Audio
              </button>

              {/* Theme */}
              <button
                onClick={() => {
                  onTheme();
                }}
                style={{
                  width: '100%',
                  background: 'transparent',
                  border: 'none',
                  padding: '10px 14px',
                  textAlign: 'left',
                  cursor: 'pointer',
                  color: 'var(--ui-text)',
                  fontSize: 12,
                  fontFamily: "'Courier Prime', monospace",
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  transition: 'all 0.12s',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = 'var(--ui-text)';
                  e.currentTarget.style.color = 'var(--ui-bg)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = 'transparent';
                  e.currentTarget.style.color = 'var(--ui-text)';
                }}
              >
                <span></span> Theme: {themeLabel}
              </button>
            </div>
          )}
        </div>

        {/* Friends Button */}
        {onFriends && (
          <button
            onClick={onFriends}
            title="Friends"
            style={{
              background: 'var(--ui-surface)',
              border: '1px solid var(--ui-line)',
              color: 'var(--ui-muted)',
              padding: '6px 11px',
              cursor: 'pointer',
              fontFamily: "'Courier Prime', monospace",
              fontSize: 14,
              fontWeight: 700,
              transition: 'all 0.12s',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.color = 'var(--ui-text)';
              e.currentTarget.style.borderColor = 'var(--ui-text)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.color = 'var(--ui-muted)';
              e.currentTarget.style.borderColor = 'var(--ui-line)';
            }}
          >

          </button>
        )}
      </div>
    </div>
  );
}

